package com.moji.offline.data.article

import com.moji.offline.resources.Res
import kotlinx.serialization.SerialName
import kotlinx.serialization.Serializable
import kotlinx.serialization.json.Json

/**
 * Metadata the native shell needs around the original H5 article body.
 *
 * Generated by `tools/build_article_assets.py` from the captured
 * `reference/moji-api/articles/{id}/detail.json` (fields keep the API names).
 */
@Serializable
data class ArticleMeta(
    val id: String,
    val title: String = "",
    val authorId: String = "",
    val authorName: String = "",
    val columnId: String = "",
    @SerialName("columnTitle") val columnTitle: String = "",
    /** OSS object key; used online when no bundled cover exists. */
    val coverId: String = "",
    /** Cover already bundled for the Discover tab (`files/find/articles/{file}`). */
    val coverFile: String = "",
    val audioId: String = "",
    val audioDuration: Int = 0,
    val publishedAt: String = "",
    val updatedAt: String = "",
    val previousId: String = "",
    val nextId: String = "",
    val transHideType: String = "0",
    val levelTags: List<String> = emptyList(),
    val isVIP: Boolean = false,
)

/**
 * Reads the generated article cache. Bodies are byte-identical copies of the
 * captured `body.html`; nothing is converted or rewritten on the way in.
 */
object ArticleCatalog {

    private const val META_PREFIX = "files/article_detail/"
    private val json = Json { ignoreUnknownKeys = true }

    suspend fun meta(articleId: String): ArticleMeta? {
        val bytes = runCatching { Res.readBytes("$META_PREFIX$articleId.json") }.getOrNull() ?: return null
        return runCatching { json.decodeFromString<ArticleMeta>(bytes.decodeToString()) }.getOrNull()
    }

    /** Original body HTML (UTF-8), unchanged. */
    suspend fun body(articleId: String): String? {
        val bytes = runCatching { Res.readBytes("$META_PREFIX$articleId.html") }.getOrNull() ?: return null
        return bytes.decodeToString()
    }
}
